 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if cells:
            r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
            mask = {(r-r0, c-c0) for r, c in cells}
            oh = max(r for r, c in cells)-r0+1
            ow = max(c for r, c in cells)-c0+1
            objects.append((min(c for r, c in cells), color, oh, ow, mask))
    objects.sort()
    out = [[0]*w for _ in range(h)]
    y = x = 0
    prev_h = prev_w = 0
    for i, (_, color, oh, ow, mask) in enumerate(objects):
        if i:
            y += prev_h - 1
            x += prev_w - 1
        for dy, dx in mask:
            yy, xx = y+dy, x+dx
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = color
        prev_h, prev_w = oh, ow
    return out
